WITH RankedPosts AS (SELECT p.Id, p.Title, p.CreationDate, p.Score, p.ViewCount, p.OwnerUserId, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS RowNum, COUNT(*) OVER (PARTITION BY p.OwnerUserId) AS PostCount FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR AND NOT (p.Score IS NULL)), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, u.Reputation, COALESCE(SUM(v.BountyAmount), 0) AS TotalBounty, COUNT(DISTINCT p.Id) AS QuestionCount, SUM(p.ViewCount) AS TotalViews FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId AND p.PostTypeId = 1 LEFT JOIN Votes AS v ON p.Id = v.PostId AND v.VoteTypeId = 8 GROUP BY u.Id, u.DisplayName, u.Reputation HAVING COUNT(DISTINCT p.Id) > 5), UserBadges AS (SELECT b.UserId, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b GROUP BY b.UserId) SELECT tu.UserId, tu.DisplayName, tu.Reputation, tu.QuestionCount, tu.TotalViews, ub.BadgeNames, p.Title, p.CreationDate, p.Score, p.ViewCount, r.RowNum, r.PostCount FROM TopUsers AS tu LEFT JOIN UserBadges AS ub ON tu.UserId = ub.UserId JOIN RankedPosts AS r ON tu.UserId = r.OwnerUserId AND r.RowNum = 1 JOIN Posts AS p ON p.Id = r.Id WHERE p.Score > (SELECT AVG(Score) FROM Posts WHERE PostTypeId = 1) ORDER BY tu.TotalViews DESC, tu.Reputation DESC NULLS FIRST